const db = require('better-sqlite3')('/workspace/world.db');

console.log('=== ORDER ===');
const orders = db.prepare(\"SELECT * FROM orders WHERE order_id LIKE '%E0E671%'\").all();
orders.forEach(r => { Object.entries(r).forEach(([k,v]) => console.log('  '+k+': '+v)); });

console.log('\n=== ORDER ITEMS ===');
const items = db.prepare(\"SELECT * FROM order_items WHERE order_id LIKE '%E0E671%'\").all();
items.forEach(r => { Object.entries(r).forEach(([k,v]) => console.log('  '+k+': '+v)); console.log('  ---'); });

console.log('\n=== PRODUCT: Aurora Smart Desk Lamp Pro ===');
const prods = db.prepare(\"SELECT product_id, name, warranty_months, return_window_days, brand, category, subcategory, description FROM products WHERE name LIKE '%Aurora Smart Desk Lamp%'\").all();
prods.forEach(r => { Object.entries(r).forEach(([k,v]) => console.log('  '+k+': '+v)); });

console.log('\n=== VARIANTS ===');
if (prods.length > 0) {
  const vars = db.prepare('SELECT * FROM rt_variants WHERE product_id = ?').all(prods[0].product_id);
  vars.forEach(r => { Object.entries(r).forEach(([k,v]) => console.log('  '+k+': '+v)); console.log('  ---'); });
}

db.close();
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Full product return/refund policy fields
console.log('=== RETURN POLICY FOR PROD-73FAB4 ===');
const prod = db.prepare('SELECT product_id, name, return_window_days, restocking_fee_pct, warranty_months, price, current_price FROM products WHERE product_id = ?').get('PROD-73FAB4');
console.log(JSON.stringify(prod, null, 2));

// Order item details
console.log('\n=== ORDER ITEM ITEM-E5801A ===');
const item = db.prepare('SELECT * FROM order_items WHERE oi_id = ?').get('ITEM-E5801A');
console.log(JSON.stringify(item, null, 2));

// Order status & date
console.log('\n=== ORDER STATUS ===');
const order = db.prepare('SELECT order_id, status, order_date, shipping_status, delivery_date FROM orders WHERE order_id = ?').get('ORD-E0E671');
console.log(JSON.stringify(order, null, 2));

// Current time from world_meta
console.log('\n=== CURRENT TIME ===');
const time = db.prepare(\"SELECT value FROM world_meta WHERE key = 'current_time'\").get();
console.log(time ? time.value : 'not found');

db.close();
"
